def frequencies(names):
    result={}
    for name in names:
        result[name]=result.get(name,0)+1
    return result

def leaders(records):
    if not records:
        return []
    highest=max(records.values())
    result=[]
    for key,value in records.items():
        if value==highest:
            result.append(key)
    return sorted(result)

def subject_totals(records):
    totals={}
    for subject,minutes in records:
        totals[subject]=totals.get(subject,0)+minutes
    return totals

def count_at_least(values,threshold):
    count=0
    for value in values:
        if value>=threshold:
            count+=1
    return count

def mean_minutes(values):
    if not values:
        return 0
    total=0
    for value in values:
        total+=value
    return total/len(values)

def sum_before_stop(values):
    total=0
    for value in values:
        if value==-1:
            break
        total+=value
    return total

def build_report(records,target):
    total=0
    count=0
    for subject,minutes in records:
        total+=minutes
        if minutes>=30:
            count+=1
    return [total,len(records),count,total/target*100]

